# Surah At-Tawbah (chapter 9) — part 13: ayat 115-124 (IDs 1350-1359)
SURAH = 9

ENTRIES = {
1350: (
"اور — اللہ — کو — لائق نہیں ، کہ — وہ — کسی قوم — کو — گمراہ — کر دے — اس — کے ہدایت کے بعد — جب تک — وہ — ان — کے لیے — واضح نہ کر دے — وہ — چیز — جس — سے — وہ — بچیں — بے شک — اللہ — ہر چیز کا — جاننے والا ہے",
"""۱۔ اللہ — ہدایت کے بعد عذاب — نہیں دیتا — جب تک واضح نہ کر دے۔
۲۔ ’’وَمَا كَانَ اللَّهُ لِيُضِلَّ قَوْمًا بَعْدَ إِذْ هَدَاهُمْ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَ إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ‘‘ — اور — اللہ — کو — لائق نہیں ، کہ — وہ — کسی قوم — کو — گمراہ — کر دے — اس — کے ہدایت کے بعد — جب تک — وہ — ان — کے لیے — واضح نہ کر دے — وہ — چیز — جس — سے — وہ — بچیں — بے شک — اللہ — ہر چیز کا — جاننے والا ہے — یعنی اللہ — ہدایت کے بعد — کسی قوم کو — گمراہ نہیں کرتا — جب تک — ان کے لیے — واضح نہ کر دے — وہ — چیز — جس سے — وہ — بچیں۔
۳۔ عملی سبق: علم — پہلے — پھر — عمل؛ اللہ کبھی ناحق ذمہ داری نہیں ڈالتا۔"""
),
1351: (
"بے شک — اللہ — کی ملکیت ہے — آسمانوں اور زمین کی — وہ — زندگی دیتا اور — موت دیتا ہے — اور — اللہ کے سوا — آپ کا — کوئی — کارساز — ہے — نہ — کوئی مددگار",
"""۱۔ اللہ — آسمان اور زمین کا مالک — زندگی اور موت کا — بادشاہ۔
۲۔ ’’إِنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ يُحْيِي وَيُمِيتُ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ‘‘ — بے شک — اللہ — کی ملکیت ہے — آسمانوں اور زمین کی — وہ — زندگی دیتا اور — موت دیتا ہے — اور — اللہ کے سوا — آپ کا — کوئی — کارساز — ہے — نہ — کوئی مددگار — یعنی اللہ — کے سوا کسی — کی مدد نہیں مل سکتی۔
۳۔ عملی سبق: اللہ پر — بھروسہ کریں؛ وہ — سب کا — کارساز ہے۔"""
),
1352: (
"اللہ — نے — نبیؐ — پر توبہ — قبول کر لی — اور — مہاجرین اور انصار — پر — جنہوں نے — اس — کے ساتھ — شدت کی گھڑی میں — پیروی کی — یہاں تک کہ — ان — میں سے — ایک — گروہ — کے دلوں کے — مائل ہونے کے قریب — ہو گئے تھے — پھر — اس نے — ان — کی توبہ قبول کی — بے شک — وہ — ان — پر — مہربان رحم کرنے والا ہے",
"""۱۔ تبوک کی مہم — مہاجرین اور انصار — کی توبہ — اللہ نے قبول کر لی۔
۲۔ ’’لَقَد تَّابَ اللَّهُ عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالْأَنصَارِ الَّذِينَ اتَّبَعُوهُ فِي سَاعَۃِ الْعُسْرَۃِ مِن بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُ بِهِمْ رَءُوفٌ رَّحِيمٌ‘‘ — اللہ — نے — نبیؐ — پر توبہ — قبول کر لی — اور — مہاجرین اور انصار — پر — جنہوں نے — اس — کے ساتھ — شدت کی گھڑی میں — پیروی کی — یہاں تک کہ — ان — میں سے — ایک — گروہ — کے دلوں کے — مائل ہونے کے قریب — ہو گئے تھے — پھر — اس نے — ان — کی توبہ قبول کی — بے شک — وہ — ان — پر — مہربان رحم کرنے والا ہے — یعنی تبوک کی شدت میں — کچھ مؤمنوں کے دل — مائل ہونے لگے تھے — مگر — اللہ — نے — ان کی توبہ قبول کر لی۔
۳۔ عملی سبق: شدت میں مقام — جہاد بدلتا ہے؛ اللہ کی رحمت — کمزور گھڑیوں میں — بھی حاضر ہے۔"""
),
1353: (
"اور — ان تین لوگوں — پر — جو — پیچھے رہ گئے — یہاں تک کہ — جب — زمین — اپنی وسعت — کے باوجود — ان پر تنگ ہو گئی — اور — ان کے لیے — اپنی جان — تنگ ہو گئی — اور — وہ — گمان — کرنے لگے — کہ — اللہ — کے سوا — کوئی پناہ — نہیں — مگر — اس — کی طرف — پھر — اس نے — ان کی توبہ قبول کی — تاکہ — وہ — توبہ کریں — بے شک — اللہ — ہی توبہ قبول کرنے والا مہربان ہے",
"""۱۔ تبوک — تین — پیچھے رہ جانے والوں کی توبہ — اللہ نے قبول کی (داستانِ کعب بن مالکؓ اور ان کے ساتھی)۔
۲۔ ’’وَعَلَى الثَّلَاثَۃِ الَّذِينَ خُلِّفُوا حَتَّىٰ إِذَا ضَاقَتْ عَلَيْهِمُ الْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوا أَن لَّا مَلْجَأَ مِنَ اللَّهِ إِلَّا إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوا إِنَّ اللَّهَ هُوَ التَّوَّابُ الرَّحِيمُ‘‘ — اور — ان تین لوگوں — پر — جو — پیچھے رہ گئے — یہاں تک کہ — جب — زمین — اپنی وسعت — کے باوجود — ان پر تنگ ہو گئی — اور — ان کے لیے — اپنی جان — تنگ ہو گئی — اور — وہ — گمان — کرنے لگے — کہ — اللہ — کے سوا — کوئی پناہ — نہیں — مگر — اس — کی طرف — پھر — اس نے — ان کی توبہ قبول کی — تاکہ — وہ — توبہ کریں — بے شک — اللہ — ہی توبہ قبول کرنے والا مہربان ہے — یعنی تین — پیچھے رہنے والوں کی توبہ — قبول کی گئی — کہ نہ زمین میں پناہ — اور نہ اپنی جانوں میں سکون — تھا۔
۳۔ عملی سبق: توبہ — اللہ — ہمیشہ — قبول کرتا ہے — مگر — اپنی سزا سے بچنے کے لیے — سچی توبہ — ضروری ہے۔"""
),
1354: (
"اے — ایمان والو — اللہ سے ڈرو — اور — سچ — بولنے والوں کے ساتھ — ہو جاؤ",
"""۱۔ سچائی — مؤمنوں کا لازمہ۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ‘‘ — اے — ایمان والو — اللہ سے ڈرو — اور — سچ — بولنے والوں کے ساتھ — ہو جاؤ — یعنی اہلِ ایمان کو — اللہ سے ڈرنے اور سچ بولنے والوں کے ساتھ ہونے کا — حکم ہے۔
۳۔ عملی سبق: سچائی — کبھی چھوڑو نہیں — چاہے — تنہا — ہو جاؤ۔"""
),
1355: (
"اہلِ مدینہ اور ان کے آس پاس — رہنے والے اعرابیوں — کے لیے — رسولؐ سے — پیچھے رہنا — لائق نہیں — اور — نہ یہ — کہ — وہ — اپنی جانوں کو — اس کی جان — پر — ترجیح دیں — یہ — اس لیے کہ — انہیں — اللہ کی راہ میں — پیاس، تھکن اور بھوک — پہنچتی ہے — اور — وہ — ایسی جگہ — پر قدم نہیں رکھتے — جو کافروں کو — غصہ دلائے — اور — کسی دشمن سے — جو — کچھ پاتے ہیں — اس کا — انہیں — نیک عمل — لکھا جاتا ہے — بے شک — اللہ — نیکوکاروں کا اجر — ضائع نہیں کرتا",
"""۱۔ مدینہ کے اہل اور آس پاس اعرابی — رسولؐ سے پیچھے نہیں رہ سکتے۔
۲۔ ’’مَا كَانَ لِأَهْلِ الْمَدِينَۃِ وَمَنْ حَوْلَهُم مِّنَ الْأَعْرَابِ أَن يَتَخَلَّفُوا عَن رَّسُولِ اللَّهِ وَلَا يَرْغَبُوا بِأَنفُسِهِمْ عَن نَّفْسِهِ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌ وَلَا نَصَبٌ وَلَا مَخْمَصَۃٌ فِي سَبِيلِ اللَّهِ وَلَا يَطَئُونَ مَوْطِئًا يَغِيظُ الْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّ نَيْلًا إِلَّا كُتِبَ لَهُم بِهِ عَمَلٌ صَالِحٌ إِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ‘‘ — اہلِ مدینہ اور ان کے آس پاس — رہنے والے اعرابیوں — کے لیے — رسولؐ سے — پیچھے رہنا — لائق نہیں — اور — نہ یہ — کہ — وہ — اپنی جانوں کو — اس کی جان — پر — ترجیح دیں — یہ — اس لیے کہ — انہیں — اللہ کی راہ میں — پیاس، تھکن اور بھوک — پہنچتی ہے — اور — وہ — ایسی جگہ — پر قدم نہیں رکھتے — جو کافروں کو — غصہ دلائے — اور — کسی دشمن سے — جو — کچھ پاتے ہیں — اس کا — انہیں — نیک عمل — لکھا جاتا ہے — بے شک — اللہ — نیکوکاروں کا اجر — ضائع نہیں کرتا — یعنی مدینہ کے اہل — رسولؐ سے پیچھے نہیں رہ سکتے؛ ان کے ہر قدم اور ہر تکلیف — نیک عمل — لکھی جاتی ہے۔
۳۔ عملی سبق: رسولؐ کی پیروی — ہر قیمت پر — کریں — اللہ ضائع نہیں کرتا۔"""
),
1356: (
"اور — وہ — چھوٹا — یا بڑا — خرچ — کرتے ہیں — اور — وہ — کسی وادی — کو — عبور نہیں کرتے — مگر — ان کے لیے — لکھا جاتا ہے — تاکہ — اللہ — انہیں — ان کے — سب سے بہتر عمل — کا بدلہ دے",
"""۱۔ چھوٹا یا بڑا خرچ — سب — لکھا جاتا ہے۔
۲۔ ’’وَلَا يُنفِقُونَ نَفَقَۃً صَغِيرَۃً وَلَا كَبِيرَۃً وَلَا يَقْطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمْ لِيَجْزِيَهُمُ اللَّهُ أَحْسَنَ مَا كَانُوا يَعْمَلُونَ‘‘ — اور — وہ — چھوٹا — یا بڑا — خرچ — کرتے ہیں — اور — وہ — کسی وادی — کو — عبور نہیں کرتے — مگر — ان کے لیے — لکھا جاتا ہے — تاکہ — اللہ — انہیں — ان کے — سب سے بہتر عمل — کا بدلہ دے — یعنی ہر خرچ — چاہے تھوڑا ہو — اور ہر قدم — لکھا جاتا ہے — اللہ — بہترین بدلہ — دیتا ہے۔
۳۔ عملی سبق: چھوٹا خرچ — بھی — اللہ کے نزدیک — بے کار نہیں۔"""
),
1357: (
"مؤمنوں — کے لیے — سب کا — جہاد میں نکلنا — ضروری نہیں — پس — کیوں نہ — ہر گروہ میں سے — ایک طائفہ — نکلے — تاکہ — وہ — دین میں — تفقہ حاصل کریں — اور — اپنی قوم — کو — اس — کے لوٹنے پر — نصیحت کریں — شاید — وہ — بچ جائیں",
"""۱۔ ہر — کوئی جہاد میں — نہیں نکلتا؛ دینی تعلیم کا — بھی — اہم فریضہ ہے۔
۲۔ ’’وَمَا كَانَ الْمُؤْمِنُونَ لِيَنفِرُوا كَافَّۃً فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَۃٍ مِّنْهُمْ طَائِفَۃٌ لِّيَتَفَقَّهُوا فِي الدِّينِ وَلِيُنذِرُوا قَوْمَهُمْ إِذَا رَجَعُوا إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ‘‘ — مؤمنوں — کے لیے — سب کا — جہاد میں نکلنا — ضروری نہیں — پس — کیوں نہ — ہر گروہ میں سے — ایک طائفہ — نکلے — تاکہ — وہ — دین میں — تفقہ حاصل کریں — اور — اپنی قوم — کو — اس — کے لوٹنے پر — نصیحت کریں — شاید — وہ — بچ جائیں — یعنی ہر کوئی — جہاد میں نہیں جاتا — کچھ کو — دینی تعلیم — حاصل کر کے — قوم کو سمجھانا — ہوتا ہے؛ یہ — ایک — فرضِ کفایہ ہے۔
۳۔ عملی سبق: جہاد — کے ساتھ — دینی تعلیم — بھی — ایک اہم فریضہ ہے۔"""
),
1358: (
"اے — ایمان والو — ان کافروں سے — جو — تمہارے قریب — ہیں — لڑائی کرو — اور — انہیں — اپنی سختی — کا مزا چکھواؤ — اور — جان لو — کہ — اللہ — متقیوں کے ساتھ — ہے",
"""۱۔ کافروں میں — جو — سب سے قریب — ہوں — ان سے جہاد — اور — سختی۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا قَاتِلُوا الَّذِينَ يَلُونَكُم مِّنَ الْكُفَّارِ وَلْيَجِدُوا فِيكُمْ غِلْظَۃً وَاعْلَمُوا أَنَّ اللَّهَ مَعَ الْمُتَّقِينَ‘‘ — اے — ایمان والو — ان کافروں سے — جو — تمہارے قریب — ہیں — لڑائی کرو — اور — انہیں — اپنی سختی — کا مزا چکھواؤ — اور — جان لو — کہ — اللہ — متقیوں کے ساتھ — ہے — یعنی پہلے — سب سے قریب — کافروں سے لڑو — اور — انہیں — اپنی سختی کا — مزا چکھواؤ — اور جان لو — اللہ — متقیوں کے ساتھ ہے۔
۳۔ عملی سبق: اللہ کی مدد — متقیوں کو — حاصل ہوتی ہے۔"""
),
1359: (
"اور — جب — کوئی سورہ — اتاری جاتی ہے — تو ان میں — کوئی — کہتا ہے — تم میں سے — کس کا — ایمان — اس — سے زیادہ — ہوا — پس — جو لوگ — ایمان لائے — ان کا — ایمان — زیادہ ہوا — اور — وہ — خوشیاں — منا رہے ہیں",
"""۱۔ قرآن — مؤمنوں کے ایمان — کو — بڑھاتا ہے۔
۲۔ ’’وَإِذَا مَا أُنزِلَتْ سُورَۃٌ فَمِنْهُم مَّن يَقُولُ أَيُّكُمْ زَادَتْهُ هَٰذِهِ إِيمَانًا فَأَمَّا الَّذِينَ آمَنُوا فَزَادَتْهُمْ إِيمَانًا وَهُمْ يَسْتَبْشِرُونَ‘‘ — اور — جب — کوئی سورہ — اتاری جاتی ہے — تو ان میں — کوئی — کہتا ہے — تم میں سے — کس کا — ایمان — اس — سے زیادہ — ہوا — پس — جو لوگ — ایمان لائے — ان کا — ایمان — زیادہ ہوا — اور — وہ — خوشیاں — منا رہے ہیں — یعنی سورہ — کے اترنے پر — مؤمن — خوش — ہوتے ہیں — کیونکہ — ان کا ایمان — بڑھ جاتا ہے۔
۳۔ عملی سبق: قرآن — ایمان بڑھانے کا — بہترین ذریعہ ہے۔"""
),
}
